// ai-excited-01 entry: "The Whale in the Teacup"
//
// A colossal luminous blue whale breaches vertically out of a tiny white
// porcelain teacup on a saucer. Its spray turns into stars, warm golden
// light rises from the tea, steam curls into constellations, and the
// whole scene sits under a deep midnight-blue night sky. One impossible
// moment of scale: the ocean, poured out of a cup of tea.
//
// The finished picture is stored in this file as one long base64 line
// (IMAGE_BASE64) and decoded at run time into entry.png. Decoding is
// fully deterministic, so every run writes the exact same bytes.
//
// Run it:
//   mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

// The finished image, base64-encoded on a single line: a 1024x1024
// JPEG of the whale breaching out of the teacup.
const IMAGE_BASE64 = '';

const MAX_BYTES = 1024 * 1024;

function main() {
  const bytes = Buffer.from(IMAGE_BASE64, 'base64');
  if (bytes.length === 0 || bytes.length > MAX_BYTES) {
    throw new Error(`decoded image is ${bytes.length} bytes, expected 1..${MAX_BYTES}`);
  }
  if (
    bytes[0] !== 0xff ||
    bytes[1] !== 0xd8 ||
    bytes[bytes.length - 2] !== 0xff ||
    bytes[bytes.length - 1] !== 0xd9
  ) {
    throw new Error('decoded bytes are not a whole JPEG (missing SOI/EOI markers)');
  }
  const outDir = process.env.MAKEFUN_OUTPUT_DIR || '/output';
  mkdirSync(outDir, { recursive: true });
  const outPath = join(outDir, 'entry.png');
  writeFileSync(outPath, bytes);
  const written = readFileSync(outPath);
  if (!written.equals(bytes)) {
    throw new Error('round-trip check failed: written bytes differ from decoded bytes');
  }
  console.log(`wrote ${outPath} (${bytes.length} bytes, round-trip verified)`);
}

main();
